#!/usr/bin/env python3
# ============================================================
#  LA GALERA AUTOPARTES - Instalador Universal v6.0
#  Funciona en: Android (Termux), Windows, Linux y macOS.
#  Uso: python instalar.py
# ============================================================
import base64, os, sys, json

ARCHIVOS = {
    'index.html': '',
    'app.html': '',
    'server.py': '',
    'manifest.json': 'eyJuYW1lIjoiTGEgR2FsZXJhIiwic2hvcnRfbmFtZSI6IkdhbGVyYSIsInN0YXJ0X3VybCI6Ii4vYXBwLmh0bWwiLCJkaXNwbGF5Ijoic3RhbmRhbG9uZSIsImJhY2tncm91bmRfY29sb3IiOiIjMGYxNzJhIiwidGhlbWVfY29sb3IiOiIjMGYxNzJhIn0K',
    'productos/placeholder.png': ''

}

def principal():
    print('=' * 58)
    print('  INSTALADOR LA GALERA AUTOPARTES v6.0')
    print('  E-commerce + ERP + IA + FacturaLo SAT (CFDI 4.0)')
    print('=' * 58)

    aqui = os.path.dirname(os.path.abspath(__file__))
    os.chdir(aqui)
    for nombre, b64 in ARCHIVOS.items():
        ruta = os.path.join(aqui, nombre)
        os.makedirs(os.path.dirname(ruta) or aqui, exist_ok=True)
        with open(ruta, 'wb') as f:
            f.write(base64.b64decode(b64))
        print('  [ok] ' + nombre)

    if not os.path.exists('db_galera.json'):
        db = {
          "version": 1, "folio_consecutivo": 1, "updated_at": "",
          "inventario": [
            {"id": 1001, "cat": "Faros y Parrillas", "desc": "Faro Derecho Nissan Versa 2015-2019", "precio": 1450.00, "stock": 4, "prov": "DEPO", "img": ""},
            {"id": 1002, "cat": "Calaveras Traseras", "desc": "Calavera Izquierda VW Vento 2014-2020", "precio": 1180.00, "stock": 3, "prov": "TYC", "img": ""},
            {"id": 1003, "cat": "Espejos Laterales", "desc": "Espejo Electrico Chevrolet Aveo 2018-2023", "precio": 950.00, "stock": 2, "prov": "POLYWAY", "img": ""},
            {"id": 1004, "cat": "Cofres y Defensas", "desc": "Fascia Delantera Nissan NP300 2016-2022", "precio": 2350.00, "stock": 5, "prov": "TONG YANG", "img": ""}
          ],
          "ventas": [], "pedidos": [], "caja": [], "mensajes": [],
          "config": {
            "whats": "2225738872",
            "dir": "Av. 44 Pte. 1703, Col. Cleotilde Torres, Puebla",
            "horario": "Lun-Vie 9:00 - 18:00 - Sab 9:00 - 14:00",
            "ia": {},
            "integraciones": {},
            "facturalo": {
              "entorno": "produccion",
              "url_prod": "https://sistema.facturaloplus.com/api/rest/servicio/timbrarJSON3",
              "apikey": "",
              "emisor_rfc": "XAXX010101000",
              "emisor_nombre": "LA GALERA AUTOPARTES",
              "emisor_regimen": "612",
              "emisor_cp": "72050",
              "serie": "LG",
              "receptor_default": {"rfc": "XAXX010101000", "nombre": "PUBLICO EN GENERAL", "cp": "72050", "regimen": "616", "uso_cfdi": "S01"}
            }
          }
        }
        with open('db_galera.json', 'w', encoding='utf-8') as f:
            json.dump(db, f, ensure_ascii=False, indent=2)
        print('  [ok] db_galera.json (datos iniciales de ejemplo)')
    else:
        print('  [--] db_galera.json existente: se conserva toda tu informacion')

    for carpeta in ('facturas', 'backups', 'archivo', 'productos'):
        os.makedirs(carpeta, exist_ok=True)

    sistema = sys.platform
    print()
    print('  Listo. Para arrancar el servidor:')
    print('    python server.py')
    print()
    print('  Sitio web     : http://localhost:8000/index.html')
    print('  Panel ERP     : http://localhost:8000/app.html')
    print('  Red local     : http://TU_IP:8000/index.html')
    print('  Feed catálogo : http://localhost:8000/api/feed.csv')
    print()
    if sistema.startswith('win'):
        print('  WINDOWS: crea acceso directo y ejecuta galera-start.bat')
        try:
            with open('galera-start.bat', 'w') as f:
                f.write('@echo off\r\ncd /d "%~dp0"\r\npython server.py\r\npause\r\n')
            with open('galera-stop.bat', 'w') as f:
                f.write('@echo off\r\ntaskkill /f /im python.exe /fi "WINDOWTITLE eq LaGalera*"\r\n')
            print('  [ok] galera-start.bat y galera-stop.bat creados')
        except Exception:
            pass
    else:
        bin_dir = os.path.join(os.path.expanduser('~'), 'bin')
        os.makedirs(bin_dir, exist_ok=True)
        gal = os.path.join(bin_dir, 'galera')
        with open(gal, 'w') as f:
            f.write('#!/data/data/com.termux/files/usr/bin/sh\n')
            f.write(f'cd "{aqui}"\ntermux-wake-lock >/dev/null 2>&1 || true\n')
            f.write('if [ -f watchdog.pid ] && kill -0 "$(cat watchdog.pid)" 2>/dev/null; then\n  echo "Servidor ya activo"\nelse\n  nohup sh watchdog.sh >/dev/null 2>&1 &\n  echo $! > watchdog.pid\n  echo "Servidor 24/7 iniciado"\nfi\n')
            f.write('if [ "$1" != "--no-open" ]; then am start -a android.intent.action.VIEW -d "http://localhost:8000/index.html" >/dev/null 2>&1 || true; fi\n')
        os.chmod(gal, 0o755)
        with open(os.path.join(bin_dir, 'galera-stop'), 'w') as f:
            f.write('#!/data/data/com.termux/files/usr/bin/sh\n')
            f.write(f'[ -f "{aqui}/watchdog.pid" ] && kill "$(cat "{aqui}/watchdog.pid")" 2>/dev/null\n')
            f.write('pkill -f "python server.py" 2>/dev/null || true\ntermux-wake-unlock >/dev/null 2>&1 || true\necho "Servidor detenido"\n')
        os.chmod(os.path.join(bin_dir, 'galera-stop'), 0o755)
        with open('watchdog.sh', 'w') as f:
            f.write('#!/data/data/com.termux/files/usr/bin/sh\n')
            f.write(f'cd "{aqui}"\ntermux-wake-lock >/dev/null 2>&1 || true\nwhile true; do\n  python server.py >> server.log 2>&1\n  sleep 2\ndone\n')
        os.chmod('watchdog.sh', 0o755)
        bashrc = os.path.join(os.path.expanduser('~'), '.bashrc')
        if os.path.isdir(os.path.dirname(bashrc)) and os.path.exists(bashrc) and 'galera --no-open' not in open(bashrc).read():
            with open(bashrc, 'a') as f:
                f.write('export PATH="$HOME/bin:$PATH"\ngalera --no-open >/dev/null 2>&1\n')
        elif not os.path.exists(bashrc):
            with open(bashrc, 'w') as f:
                f.write('export PATH="$HOME/bin:$PATH"\ngalera --no-open >/dev/null 2>&1\n')
        print('  [ok] comandos: galera / galera-stop (arranque 24/7 en Termux)')

if __name__ == '__main__':
    principal()
